  <main class="wrap">
    <h1>Pocket Garden</h1>
    <p class="lead">Pick a plant, check its light, and mark what you've planted.</p>
    <p class="note"><strong>Heads up:</strong> your choices reset when you reload this page.</p>

    <fieldset class="filters">
      <legend>Filter plants</legend>
      <div class="filter-row">
        <button type="button" class="filter-btn" data-filter="all" aria-pressed="true">All plants</button>
        <button type="button" class="filter-btn" data-filter="sun" aria-pressed="false">Loves sun</button>
        <button type="button" class="filter-btn" data-filter="shade" aria-pressed="false">Likes shade</button>
      </div>
    </fieldset>

    <p class="status" id="status" role="status" aria-live="polite"></p>

    <ul class="grid" id="grid">
      <li class="card" data-light="sun">
        <span class="tag sun">Loves sun</span>
        <h2>Basil</h2>
        <p>A fragrant herb that likes warm, bright spots.</p>
        <button type="button" class="plant-btn">Mark as planted<span class="sr-only"> : Basil</span></button>
      </li>
      <li class="card" data-light="sun">
        <span class="tag sun">Loves sun</span>
        <h2>Sunflower</h2>
        <p>Tall and cheerful, it follows the sun across the sky.</p>
        <button type="button" class="plant-btn">Mark as planted<span class="sr-only"> : Sunflower</span></button>
      </li>
      <li class="card" data-light="shade">
        <span class="tag shade">Likes shade</span>
        <h2>Mint</h2>
        <p>A hardy herb that is happy in cooler, shadier corners.</p>
        <button type="button" class="plant-btn">Mark as planted<span class="sr-only"> : Mint</span></button>
      </li>
    </ul>
  </main>

<script>
(function () {
  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
  var filterButtons = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));
  var status = document.getElementById('status');
  var labels = { all: 'all plants', sun: 'plants that love sun', shade: 'plants that like shade' };

  function applyFilter(filter) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = filter === 'all' || card.getAttribute('data-light') === filter;
      card.hidden = !match;
      if (match) shown++;
    });
    filterButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
    });
    status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' — ' + labels[filter] + '.';
  }

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      applyFilter(btn.getAttribute('data-filter'));
    });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector('.plant-btn');
    var name = card.querySelector('h2').textContent;
    btn.addEventListener('click', function () {
      var planted = !card.classList.contains('planted');
      card.classList.toggle('planted', planted);
      btn.classList.toggle('is-planted', planted);
      btn.textContent = planted ? 'Planted' : 'Mark as planted';
      var hint = document.createElement('span');
      hint.className = 'sr-only';
      hint.textContent = ' : ' + name;
      btn.appendChild(hint);
    });
  });

  applyFilter('all');
})();
</script>
